            "text": "Using nightly on the right thumb as advised, for 4 weeks.",
            "site": {
              "text": "Right thumb"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "when": [
                  "NIGHT"
                ]
              }
            }
          }
        ],
        "note": [
          {
            "text": "Partial response after 4 weeks."
