              "text": "Right thumb and left index finger warts"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "when": [
                  "NIGHT"
                ]
              }
            }
          }
        ]
      }
    }
  ]
}

